 const supplied=buildResolutionFixturePreconditions(cases.omission_foundation_preconditions),captured=createState(supplied),capturedBefore=historyHash(captured);supplied.evidence_artifacts.find(item=>item.evidence_ref==='resolution-observation-v1').digest='0'.repeat(64);supplied.constitutive_evaluations.find(item=>item.evaluation_ref==='resolution-evaluation-v1').snapshot.sources[0].records.length=0;assert.equal(historyHash(captured),capturedBefore);
 let state=createState(buildResolutionFixturePreconditions(cases.omission_foundation_preconditions));state=applyOperation(state,omissionOperation(cases.omission_foundation_event,'omission-resolution-target',state),context).next_state;assert.equal(applyOperation(state,operationFor('resolution-evaluation-v1'),{resolved:true}).code,'RESOLUTION_CONTEXT_FIELDS');assert.equal(applyOperation(state,{...operationFor('resolution-evaluation-v1'),outcome:'RESOLVED'}).code,'RESOLUTION_OPERATION_FIELDS');
 let getterCalls=0;const accessor=operationFor('resolution-evaluation-v1');Object.defineProperty(accessor,'outcome',{enumerable:true,get(){getterCalls++;return'RESOLVED';}});assert.throws(()=>applyOperation(state,accessor),{name:'TypeError',message:'INVALID_OPERATION_DATA'});assert.equal(getterCalls,0);let proxyTraps=0;const proxy=new Proxy(operationFor('resolution-evaluation-v1'),{ownKeys(){proxyTraps++;return[];},getOwnPropertyDescriptor(){proxyTraps++;return undefined;}});assert.throws(()=>applyOperation(state,proxy),{name:'TypeError',message:'INVALID_OPERATION_DATA'});assert.equal(proxyTraps,0);const hostileGetter=buildResolutionFixturePreconditions(cases.omission_foundation_preconditions);Object.defineProperty(later(hostileGetter).expectations[0],'hostile',{enumerable:true,get(){getterCalls++;return true;}});assert.throws(()=>createState(hostileGetter),{name:'TypeError'});assert.equal(getterCalls,0);const hostileProxy=buildResolutionFixturePreconditions(cases.omission_foundation_preconditions);hostileProxy.evidence_artifacts[0]=new Proxy(hostileProxy.evidence_artifacts[0],{ownKeys(){proxyTraps++;return[];},getOwnPropertyDescriptor(){proxyTraps++;return undefined;}});assert.throws(()=>createState(hostileProxy),{name:'TypeError'});assert.equal(proxyTraps,0);
 const{catalog}=validateCatalog();assert.deepEqual(scenario.requirement_ids,['JN-CORE-0_2-REQ-D092','JN-CORE-0_2-REQ-D093','JN-CORE-0_2-REQ-D094','JN-CORE-0_2-REQ-D095']);for(const id of scenario.requirement_ids){const requirement=catalog.requirements.find(item=>item.requirement_id===id);assert.deepEqual(requirement.stateful_positive_scenario_refs,[scenario.scenario_id]);assert.deepEqual(requirement.stateful_negative_scenario_refs,[scenario.scenario_id]);assert.deepEqual(requirement.stateful_test_refs,['tools/core-conformance/test/stateful-history-reference.test.mjs#D092-D095-omission-resolution']);assert.ok(requirement.explicit_non_goals.some(item=>/runtime persistence|truth|supersession|canonical time/.test(item)));}
