 state=applyOperation(state,{operation:'APPEND',log:'MANAGEMENT_LOG',record:{identity:'decided-object-target',payload:{}}}).next_state;
 state=applyOperation(state,{operation:'APPEND',log:'MANAGEMENT_LOG',record:{identity:'context-only-target',payload:{}}}).next_state;
 const makeOperation=(identity,objectRefs=undefined)=>{const payload={event_type:'HUMAN_DECISION',event_id:identity,actor_ref:'opaque-actor',scope_ref:'opaque-scope',...structuredClone(contextFields),occurred_at:'2026-11-07T12:00:00Z',recorded_at:'2026-11-07T12:00:01Z'};if(objectRefs!==undefined)payload.object_refs=objectRefs;return{operation:'APPEND',log:'AUDIT_LOG',record:{identity,payload}};};
 const assertObserved=(outcome,expected,beforeState,beforeOperation,beforeContext)=>{assert.equal(outcome.accepted,expected.accepted);assert.equal(outcome.code,expected.code);assert.equal(outcome.history_delta,expected.delta);assert.equal(stable(beforeState),expected.beforeStable);assert.deepEqual(expected.operation,beforeOperation);assert.deepEqual(expected.context,beforeContext);if(expected.accepted){assert.notEqual(outcome.before_hash,outcome.after_hash);assert.equal(outcome.next_state.logs.AUDIT_LOG.length,beforeState.logs.AUDIT_LOG.length+1);}else{assert.equal(outcome.before_hash,outcome.after_hash);assert.equal(stable(outcome.next_state),expected.beforeStable);}return outcome;};
 const observe=(base,operation,expected)=>{const beforeStable=stable(base),operationCopy=structuredClone(operation),contextCopy=structuredClone(context),outcome=applyOperation(base,operation,context);return assertObserved(outcome,{...expected,beforeStable,operation:operationCopy,context:contextCopy},base,operation,context);};
 const positiveOperation=makeOperation('decision-role-boundary-valid',[canonical('MANAGEMENT_LOG','decided-object-target')]),positive=observe(state,positiveOperation,{accepted:true,code:'APPENDED',delta:1});assert.equal(stable(positive.next_state.logs.AUDIT_LOG.at(-1).payload.management_refs),stable(contextFields.management_refs));assert.equal(stable(positive.next_state.logs.AUDIT_LOG.at(-1).payload.evidence_refs),stable(contextFields.evidence_refs));assert.equal(positive.next_state.logs.AUDIT_LOG.at(-1).payload.schema_ref,contextFields.schema_ref);state=positive.next_state;
 const negatives=[
  [makeOperation('decision-derived-view-object',[{ref_type:'DERIVED_VIEW',view_ref:'derived-view-token'}]),'INVALID_OBJECT_REF'],
  [makeOperation('decision-external-artifact-object',[{ref_type:'EXTERNAL_ARTIFACT',artifact_ref:'external-artifact-token'}]),'INVALID_OBJECT_REF'],
  [makeOperation('decision-unresolved-object-with-context',[canonical('MANAGEMENT_LOG','missing-decided-object')]),'UNRESOLVED_REFERENCE'],
  [makeOperation('decision-empty-object-refs-with-context',[]),'INVALID_HUMAN_DECISION_SHAPE'],
  [makeOperation('decision-missing-object-refs-with-context'),'INVALID_HUMAN_DECISION_SHAPE']
 ];
 for(const[operation,code]of negatives){const beforeStable=stable(state),operationCopy=structuredClone(operation),contextCopy=structuredClone(context),outcome=observe(state,operation,{accepted:false,code,delta:0}),expected={accepted:false,code,delta:0,beforeStable,operation:operationCopy,context:contextCopy};for(const mutate of [candidate=>{candidate.accepted=true;},candidate=>{candidate.code='APPENDED';},candidate=>{candidate.history_delta=1;},candidate=>{candidate.after_hash='mutated';},candidate=>{candidate.next_state.logs.MANAGEMENT_LOG=[];}]){const mutant=structuredClone(outcome);mutate(mutant);assert.throws(()=>assertObserved(mutant,expected,state,operation,context));}}
 let getterCalls=0;const accessorPayload=makeOperation('decision-hostile-accessor',[canonical('MANAGEMENT_LOG','decided-object-target')]).record.payload;Object.defineProperty(accessorPayload.management_refs[0],'identity',{enumerable:true,get(){getterCalls++;return'context-only-target';}});assert.throws(()=>applyOperation(state,{operation:'APPEND',log:'AUDIT_LOG',record:{identity:'decision-hostile-accessor',payload:accessorPayload}},context),{name:'TypeError',message:'INVALID_OPERATION_DATA'});assert.equal(getterCalls,0);
 let proxyTraps=0;const nestedProxy=new Proxy(canonical('MANAGEMENT_LOG','decided-object-target'),{ownKeys(){proxyTraps++;return[];},getOwnPropertyDescriptor(){proxyTraps++;return undefined;}});assert.throws(()=>applyOperation(state,makeOperation('decision-hostile-proxy',[nestedProxy]),context),{name:'TypeError',message:'INVALID_OPERATION_DATA'});assert.equal(proxyTraps,0);
 const cases=load('conformance/core-lite-v0.2/scenarios/history-reference.cases.json'),scenario=cases.scenarios.find(item=>item.scenario_id==='enforce-human-decision-object-role-boundaries'),{catalog}=validateCatalog(),ids=['JN-CORE-0_2-REQ-D047','JN-CORE-0_2-REQ-D048','JN-CORE-0_2-REQ-D051-A','JN-CORE-0_2-REQ-D051-B'];assert.deepEqual(scenario.requirement_ids,ids);for(const id of ids){const requirement=catalog.requirements.find(item=>item.requirement_id===id);assert.deepEqual(requirement.stateful_positive_scenario_refs,[scenario.scenario_id]);assert.deepEqual(requirement.stateful_negative_scenario_refs,[scenario.scenario_id]);assert.deepEqual(requirement.stateful_test_refs,['tools/core-conformance/test/stateful-history-reference.test.mjs#D047-D048-D051-object-role-boundaries']);}assert.match(catalog.requirements.find(item=>item.requirement_id==='JN-CORE-0_2-REQ-D047').ambiguity_notes,/not a claimed canonical Core serialization/);assert.match(catalog.requirements.find(item=>item.requirement_id==='JN-CORE-0_2-REQ-D048').ambiguity_notes,/not a claimed canonical Core serialization/);assert.match(catalog.requirements.find(item=>item.requirement_id==='JN-CORE-0_2-REQ-D051-A').ambiguity_notes,/opaque context/);assert.ok(catalog.requirements.find(item=>item.requirement_id==='JN-CORE-0_2-REQ-D051-B').explicit_non_goals.includes('do not claim D053, D054, or evidentiary sufficiency'));
