test('E-plus support integration is read-only claim-bounded and hostile-input safe',()=>{const cases=load('conformance/core-lite-v0.2/scenarios/history-reference.cases.json'),claim=cases.scenarios.find(item=>item.scenario_id==='evaluate-e-plus-claim-support'),event=cases.scenarios.find(item=>item.scenario_id==='evaluate-e-plus-event-support');for(const scenario of [claim,event]){const copy=structuredClone(scenario),first=runScenario(scenario),second=runScenario(scenario);assert.deepEqual(first,second);assert.deepEqual(scenario,copy);assert.equal(first.accepted_steps,1);assert.equal(first.rejected_steps,1);assert.equal(stable(first.log_sizes),stable({MANAGEMENT_LOG:0,SCHEMA_LOG:0,AUDIT_LOG:0}));}const supplied=structuredClone(claim.preconditions),state=createState(supplied),before=historyHash(state),operation=structuredClone(claim.steps[0].operation),operationCopy=structuredClone(operation),accepted=applyOperation(state,operation);assert.equal(accepted.accepted,true);assert.equal(accepted.code,'E_PLUS_ARTIFACT_SUPPORT_VERIFIED');assert.equal(accepted.history_delta,0);assert.equal(accepted.before_hash,accepted.after_hash);assert.equal(historyHash(state),before);assert.deepEqual(operation,operationCopy);assert.equal(Object.isFrozen(state.preconditions.e_plus_registry),true);supplied.e_plus_registry.artifacts[0].version='changed';supplied.e_plus_registry.artifacts[0].content_base64='bXV0YXRlZA==';supplied.e_plus_registry.governance_events[0].subject_refs[0].subject_ref='changed';assert.equal(historyHash(state),before);assert.throws(()=>{state.preconditions.e_plus_registry.artifacts[0].version='mutated';});assert.equal(applyOperation(state,operation,{supports_claim:true}).code,'E_PLUS_CONTEXT_FIELDS');let getterCalls=0;const accessor=structuredClone(operation);Object.defineProperty(accessor,'subject_ref',{enumerable:true,get(){getterCalls++;return'claim-1';}});assert.throws(()=>applyOperation(state,accessor),{name:'TypeError',message:'INVALID_OPERATION_DATA'});assert.equal(getterCalls,0);let proxyTraps=0;const proxy=new Proxy(operation,{ownKeys(){proxyTraps++;return[];},getOwnPropertyDescriptor(){proxyTraps++;return undefined;}});assert.throws(()=>applyOperation(state,proxy),{name:'TypeError',message:'INVALID_OPERATION_DATA'});assert.equal(proxyTraps,0);const hostile={e_plus_registry:{}},nested=[];hostile.e_plus_registry.deep=nested;let cursor=nested;for(let index=0;index<80;index++){const next=[];cursor.push(next);cursor=next;}assert.throws(()=>createState(hostile),{name:'TypeError',message:'INVALID_PRECONDITIONS_DATA_DEPTH_LIMIT'});const{catalog}=validateCatalog();for(const id of claim.requirement_ids){const requirement=catalog.requirements.find(item=>item.requirement_id===id);assert.ok(requirement.stateful_positive_scenario_refs.includes(claim.scenario_id));assert.ok(requirement.stateful_negative_scenario_refs.includes(claim.scenario_id));assert.deepEqual(requirement.stateful_test_refs,['tools/core-conformance/test/stateful-history-reference.test.mjs#E-plus-support-integration']);}assert.deepEqual(catalog.requirements.find(item=>item.requirement_id==='JN-CORE-0_2-REQ-D101').stateful_positive_scenario_refs,[claim.scenario_id]);});
test('exact stateful completion and projection allowlists are preserved',()=>{const{catalog}=validateCatalog();assert.equal(statefulCoverageIds.length,50);assert.equal(statefulProjectionIds.length,7);assert.deepEqual(statefulProjectionIds.slice(-5),demotedProjectionIds);for(const id of statefulCoverageIds){const requirement=catalog.requirements.find(item=>item.requirement_id===id);assert.ok(requirement.coverage_markers.includes('STATEFUL_SCENARIO_COVERED'));assert.ok(requirement.coverage_markers.includes('REQUIREMENT_COMPLETE'));assert.equal(requirement.coverage_status.length,0);}for(const id of statefulProjectionIds){const requirement=catalog.requirements.find(item=>item.requirement_id===id);assert.deepEqual(requirement.coverage_markers,['STATEFUL_PROJECTION_COVERED']);assert.ok(requirement.coverage_status.length);}for(const id of demotedProjectionIds){const requirement=catalog.requirements.find(item=>item.requirement_id===id);assert.deepEqual(requirement.coverage_status,['MISSING_POSITIVE_FIXTURE','MISSING_NEGATIVE_FIXTURE','MISSING_TEST']);assert.deepEqual(requirement.test_refs,[]);assert.ok(requirement.stateful_positive_scenario_refs.length);assert.ok(requirement.stateful_negative_scenario_refs.length);assert.ok(requirement.stateful_test_refs.length);}const d080=catalog.requirements.find(item=>item.requirement_id==='JN-CORE-0_2-REQ-D080');assert.equal(d080.implementation_status,'NOT_IMPLEMENTED');assert.deepEqual(d080.stateful_positive_scenario_refs,[]);assert.deepEqual(d080.stateful_negative_scenario_refs,[]);});
